/**
 * Bulk-import persistence: one batch of issues, the labels it introduces and the record that makes its key replayable.
 *
 * The batch is written in a single synchronous SQLite transaction, so either every row lands or none does.
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { parseJsonArray } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

/** Colour given to labels an import creates; matches the label schema default. */
const IMPORTED_LABEL_COLOR = "#94a3b8";

/** One import row, already resolved against the workspace (assignee and labels). */
export type ImportIssueDraft = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
};

/** What a successful import remembers: where it went and what it created, in file order. */
export type IssueImportRecord = {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    projectId: row.projectId as ProjectId,
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

/**
 * Writes the batch. If the key was recorded between the caller's check and
 * this transaction, nothing is written and the earlier record is returned with
 * `replayed: true`.
 */
export async function insertIssueImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  drafts: readonly ImportIssueDraft[];
}): Promise<IssueImportRecord & { replayed: boolean }> {
  return getDb().transaction((tx) => {
    const prior = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (prior) {
      return {
        replayed: true,
        projectId: prior.projectId as ProjectId,
        issueIds: parseJsonArray<IssueId>(prior.issueIds),
      };
    }

    const stamp = toIsoTimestamp(new Date());

    const labelIdByName = new Map<string, LabelId>();
    const existingLabels = tx
      .select()
      .from(labels)
      .where(orgPredicate(labels.orgId, input.orgId))
      .all();
    for (const row of existingLabels) {
      labelIdByName.set(row.name, row.id as LabelId);
    }

    for (const draft of input.drafts) {
      for (const name of draft.labelNames) {
        if (labelIdByName.has(name)) continue;
        const id = newId() as LabelId;
        tx.insert(labels)
          .values({
            id,
            orgId: input.orgId,
            name,
            color: IMPORTED_LABEL_COLOR,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, id);
      }
    }

    // Numbering continues after the highest number the project has ever used, archived rows included.
    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = highest?.value ?? 0;

    const issueIds: IssueId[] = [];
    for (const draft of input.drafts) {
      number += 1;
      const id = newId() as IssueId;

      tx.insert(issues)
        .values({
          id,
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: draft.title,
          description: draft.description,
          status: draft.status,
          priority: draft.priority,
          authorId: input.authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      const labelIds = [...new Set(draft.labelNames)].flatMap((name) => {
        const labelId = labelIdByName.get(name);
        return labelId === undefined ? [] : [labelId];
      });
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: id,
              labelId,
            })),
          )
          .run();
      }

      issueIds.push(id);
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, projectId: input.projectId, issueIds };
  });
}

