          authorId: input.authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      const labelIds = [...new Set(draft.labelNames)].flatMap((name) => {
        const labelId = labelIdByName.get(name);
        return labelId === undefined ? [] : [labelId];
      });
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: id,
              labelId,
            })),
          )
          .run();
      }

      issueIds.push(id);
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, projectId: input.projectId, issueIds };
