/**
 * Bulk issue import: file order, numbering, replays, the all-or-nothing gates
 * and the single batch announcement that the audit log, meter and search read.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { OrgId, ProjectId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** Runs the same parse the client-facing contract applies, so inputs are real `ImportIssuesInput`s. */
function batch(
  orgId: OrgId,
  projectId: ProjectId,
  rows: readonly (Partial<ImportIssueRowInput> & { title: string })[],
  importKey = "upload-0001-abcd",
) {
  return importIssuesSchema.parse({ orgId, projectId, importKey, rows });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("importsvc");
  registerEventHandlers();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("services/issue-service importIssues", () => {
  it("creates every row in file order, numbered after the project's highest number", async () => {
    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, [
        { title: "First row" },
        {
          title: "Second row",
          priority: "high",
          labels: ["bug", "bug", "ui"],
          assigneeEmail: "MEMBER@importsvc.test",
        },
        { title: "Third row", assigneeEmail: "nobody@elsewhere.test", dueAt: "2030-01-01T00:00:00.000Z" },
      ], "upload-order-0001"),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(tenant.project.id);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "First row",
      "Second row",
      "Third row",
    ]);
    expect(result.issues.map((issue) => issue.number)).toEqual([1, 2, 3]);

    const [, second, third] = result.issues;
    expect(result.issues[0]?.authorId).toBe(tenant.userIds.member);
    expect(second?.assigneeId).toBe(tenant.userIds.member);
    expect(second?.priority).toBe("high");
    expect(second?.labelIds).toHaveLength(2);
    expect(third?.assigneeId).toBeNull();
    expect(third?.dueAt).toBe("2030-01-01T00:00:00.000Z");

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Created after import" }),
    );
    expect(next.number).toBe(4);
  });

  it("replays a known key with the original issues and creates nothing", async () => {
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, [{ title: "Replay original" }], "upload-replay-0001"),
    );
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    const replay = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, [
        { title: "Different rows now" },
        { title: "And another one" },
      ], "upload-replay-0001"),
    );

    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(first.issues.map((issue) => issue.id));
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
  });

  it("treats a different key as a new import even when the rows are identical", async () => {
    const rows = [{ title: "Same rows twice" }];
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, rows, "upload-dup-0001"),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, rows, "upload-dup-0002"),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
  });

  it("refuses the whole batch over the plan quota, and a refused key is not used up", async () => {
    const quotaTenant = await createTenant("importquota", "free");
    for (let number = 1; number <= 98; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, { title: `Seed ${number}` }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        quotaTenant.actors.member,
        batch(quotaTenant.org.id, quotaTenant.project.id, [
          { title: "Batch one" },
          { title: "Batch two" },
          { title: "Batch three" },
        ], "upload-quota-0001"),
      ),
    ).rejects.toThrow(/allows no more issues/);
    expect(await issueRepo.countIssues(quotaTenant.org.id, quotaTenant.project.id)).toBe(98);

    const retry = await issueService.importIssues(
      quotaTenant.actors.member,
      batch(quotaTenant.org.id, quotaTenant.project.id, [
        { title: "Batch one" },
        { title: "Batch two" },
      ], "upload-quota-0001"),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues).toHaveLength(2);
  });

  it("refuses viewers, foreign workspaces, unknown projects and archived projects", async () => {
    const other = await createTenant("importother");
    const archivedTenant = await createTenant("importarchived");
    await projectRepo.archiveProject(archivedTenant.org.id, archivedTenant.project.id);

    await expect(
      issueService.importIssues(
        tenant.actors.viewer,
        batch(tenant.org.id, tenant.project.id, [{ title: "Viewer row" }], "upload-refuse-01"),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(other.org.id, other.project.id, [{ title: "Cross tenant" }], "upload-refuse-02"),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant.org.id, other.project.id, [{ title: "Foreign project" }], "upload-refuse-03"),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(
        archivedTenant.actors.member,
        batch(archivedTenant.org.id, archivedTenant.project.id, [{ title: "Archived" }], "upload-refuse-04"),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("publishes one issues.imported, no issue.created, and the audit, meter and search follow", async () => {
    const imported = capture("issues.imported");
    const created = capture("issue.created");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, [
        { title: "Searchable needle row" },
        { title: "Quiet row" },
      ], "upload-events-01"),
    );

    expect(created).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "upload-events-01",
      issueIds: result.issues.map((issue) => issue.id),
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 50,
      cursor: null,
    });
    const entry = audit.items.find((event) => event.metadata.importKey === "upload-events-01");
    expect(entry).toMatchObject({
      action: "issues.imported",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "upload-events-01" },
    });

    const meter = await usageRepo.getUsage(tenant.org.id);
    const recount = await usageRepo.recomputeUsage(tenant.org.id);
    expect(meter.issuesUsed).toBe(recount.issuesUsed);

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "needle",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id)).toContain(result.issues[0]?.id);
  });
});

